// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount, address nonOwner) public {
        vm.assume(nonOwner != c.owner());
        vm.assume(amount > 0);
        address someone = address(12345);
        vm.deal(someone, amount);
        vm.prank(someone);
        (bool sent,) = address(c).call{value: amount}("");
        require(sent);
        uint256 balanceBefore = address(c).balance;
        vm.prank(nonOwner);
        try c.withdraw(amount) { assertTrue(false, "withdraw by nonOwner should revert"); } catch { }
        uint256 balanceAfter = address(c).balance;
        assertEq(balanceAfter, balanceBefore);
    }
}
